/**
 * tor-js-gateway client (KPS edition).
 *
 * The gateway speaks KPS-HTTP/1 (see tor-js-gateway/PROTOCOL.md): strict
 * HTTP/1.1 syntax over KPS streams, one exchange per stream, bodies
 * delimited by stream FIN. Clients dial the gateway's `ip:port:certhash`
 * address — no URL, no CA, no DNS. In browsers the dial goes over WebRTC
 * (@kpstreams/webrtc-client); in Node it goes over QUIC via the optional
 * @kpstreams/quic-client package.
 *
 * Relay connections are HTTP CONNECT tunnels (PROTOCOL.md §4): after the
 * gateway's 200 the stream is the raw TCP byte pipe to the relay.
 */

import type { Connection, Stream } from '@kpstreams/core';
import { parseAddress } from './kpsAddress.js';
import type { DialFn } from './kpsDial.js';
import type { Log } from './Log.js';
import { ArtiSocket, type ArtiSocketCloseInfo } from './socketProvider.js';

const enc = new TextEncoder();
const dec = new TextDecoder();

/** Timeout for opening a new stream on an established KPS connection.
 * openStream() has no default timeout and can hang forever if the
 * connection dies mid-open (kps ISSUES #14), so always bound it. */
const OPEN_STREAM_TIMEOUT_MS = 20_000;

/**
 * Reject as soon as `signal` aborts, without disturbing `p` itself. Used to
 * bound one caller's wait on a shared dial: the dial keeps running, so a
 * connection that lands late is still stored and reused rather than leaked.
 */
function abortRace<T>(p: Promise<T>, signal: AbortSignal | undefined, what: string): Promise<T> {
  if (!signal) return p;
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(new Error(`${what}: timed out`));
    if (signal.aborted) return onAbort();
    signal.addEventListener('abort', onAbort, { once: true });
    p.then(resolve, reject).finally(() => signal.removeEventListener('abort', onAbort));
  });
}

interface ResponseHead {
  status: number;
  statusText: string;
  headers: Record<string, string>;
  /** Body bytes that arrived in the same chunks as the head. */
  extra: Uint8Array;
}

/**
 * Read a response head (status line + headers) from a stream reader.
 */
async function readHead(reader: ReadableStreamDefaultReader<Uint8Array>): Promise<ResponseHead> {
  let buf = new Uint8Array(0);
  for (;;) {
    const sep = findHeadEnd(buf);
    if (sep !== -1) {
      const head = dec.decode(buf.subarray(0, sep));
      const lines = head.split('\r\n');
      const m = lines[0].match(/^HTTP\/1\.1 (\d{3})\s*(.*)$/);
      if (!m) throw new Error(`malformed status line: ${lines[0]}`);
      const headers: Record<string, string> = {};
      for (const line of lines.slice(1)) {
        const i = line.indexOf(':');
        if (i === -1) continue;
        headers[line.slice(0, i).toLowerCase()] = line.slice(i + 1).trim();
      }
      return {
        status: parseInt(m[1], 10),
        statusText: m[2],
        headers,
        extra: buf.subarray(sep + 4),
      };
    }
    const { done, value } = await reader.read();
    if (done) throw new Error('stream ended before response head');
    const next = new Uint8Array(buf.length + value.length);
    next.set(buf, 0);
    next.set(value, buf.length);
    buf = next;
  }
}

function findHeadEnd(buf: Uint8Array): number {
  for (let i = 0; i + 3 < buf.length; i++) {
    if (buf[i] === 13 && buf[i + 1] === 10 && buf[i + 2] === 13 && buf[i + 3] === 10) {
      return i;
    }
  }
  return -1;
}

function concat(chunks: Uint8Array[], length: number): Uint8Array {
  const out = new Uint8Array(length);
  let off = 0;
  for (const c of chunks) {
    out.set(c, off);
    off += c.length;
  }
  return out;
}

export interface GatewayResponse {
  status: number;
  statusText: string;
  headers: Record<string, string>;
  body: Uint8Array;
}

/** Options for {@link KpsGateway}. */
export interface KpsGatewayOptions {
  /**
   * Custom KPS dialer. Defaults to the built-in WebRTC (browser) / QUIC (Node)
   * dialer, which is imported lazily so it only loads when this is omitted.
   * Inject a dialer to reach the gateway over a transport you already hold
   * (e.g. a KPS capability granted to a sandboxed worker); then the built-in
   * dialer and its `@kpstreams` client deps are never loaded.
   */
  dial?: DialFn;

  /**
   * Log for this gateway's messages, such as the one-time demo-gateway warning
   * (PROTOCOL.md §5). Omitted means they are dropped, and the demo check is
   * skipped since it would have nowhere to report.
   */
  log?: Log;
}

/**
 * A connection to one tor-js-gateway, addressed by its KPS address
 * (`ip:port:certhash`). The underlying KPS connection is dialed lazily and
 * reused; every request/tunnel is its own stream on it. Re-dials
 * automatically if the connection drops.
 */
export class KpsGateway {
  #address: string;
  #certhash: string;
  #connPromise: Promise<Connection> | null = null;
  // Per-connection teardown callbacks. The JS kps client does not reliably
  // settle streams when the connection dies (kps ISSUES #4) — a reader
  // blocked on stream.readable can hang forever — so every socket/exchange
  // registers a teardown that conn.closed triggers.
  #teardowns = new Map<Connection, Set<() => void>>();
  #closed = false;
  #dial: DialFn | undefined;
  #log: Log | undefined;
  // The demo check runs at most once per gateway, whatever the outcome: it is
  // a courtesy notice, not something to retry or repeat per request.
  #demoChecked = false;

  /**
   * @param address KPS address (`ip:port:certhash`).
   * @param options Optional {@link KpsGatewayOptions} (e.g. a custom `dial`).
   */
  constructor(address: string, options: KpsGatewayOptions = {}) {
    this.#address = address.trim();
    // Validates the address shape early and yields the certhash, which is
    // the Host value the protocol recommends (PROTOCOL.md §3.2).
    this.#certhash = parseAddress(this.#address).certhash;
    this.#dial = options.dial;
    this.#log = options.log;
  }

  /**
   * Warn once if the gateway declares itself a demonstration instance
   * (`"demo": true` in `/metadata.json`, PROTOCOL.md §5).
   *
   * Deliberately fire-and-forget: it costs one small exchange on a connection
   * that is already up, and nothing about it may delay or fail real work — a
   * gateway that never answers this is still a working gateway. Errors are
   * swallowed for the same reason, and the absent field means `false`, because
   * an older gateway cannot say.
   */
  #checkDemo(): void {
    if (this.#demoChecked || !this.#log) return;
    this.#demoChecked = true;
    void (async () => {
      const res = await this.fetch('/metadata.json', {
        signal: AbortSignal.timeout(10_000),
      });
      if (res.status !== 200) return;
      const meta = JSON.parse(new TextDecoder().decode(res.body)) as { demo?: unknown };
      if (meta.demo !== true) return;
      this.#log?.warnOnce(
        `demo-gateway:${this.#address}`,
        `Gateway ${this.#address} reports itself as a demo instance: limited capacity, ` +
        'and it may disappear at any time. Run your own gateway for anything real: ' +
        'https://github.com/ethereum/tor-js/tree/main/crates/tor-js-gateway',
      );
    })().catch(() => {
      // Unreachable, malformed, or 404 on an older gateway — all mean "no
      // warning to give", never a reason to disturb the caller.
    });
  }

  get address(): string {
    return this.#address;
  }

  /** Dial (or reuse) the KPS connection, optionally bounding this caller's wait. */
  async #connection(signal?: AbortSignal): Promise<Connection> {
    if (this.#closed) throw new Error('KpsGateway is closed');
    if (!this.#connPromise) {
      // Resolve the dialer inside the promise chain — lazy-importing the
      // built-in one only when no custom `dial` was injected — so #connPromise
      // is still assigned synchronously and concurrent callers share one dial.
      const dialP: Promise<DialFn> = this.#dial
        ? Promise.resolve(this.#dial)
        : import('./kpsDial.js').then((m) => (this.#dial = m.kpsDial));
      const p = dialP.then((dial) => dial(this.#address)).then(
        (conn) => {
          this.#teardowns.set(conn, new Set());
          // conn.closed may resolve OR reject (kps rejects it with the close
          // reason, e.g. null, on some teardowns); run cleanup either way and
          // never leave the rejection unhandled.
          const onClosed = () => {
            if (this.#connPromise === p) this.#connPromise = null;
            const teardowns = this.#teardowns.get(conn);
            this.#teardowns.delete(conn);
            for (const fn of teardowns ?? []) fn();
          };
          conn.closed.then(onClosed, onClosed);
          // The connection is up, so the demo check costs one stream on it.
          // Safe to call from here: it sets its own once-flag before fetching,
          // so the fetch's own #connection() call cannot re-trigger it.
          this.#checkDemo();
          return conn;
        },
        (err) => {
          if (this.#connPromise === p) this.#connPromise = null;
          throw err;
        },
      );
      this.#connPromise = p;
    }
    return abortRace(this.#connPromise, signal, `dial ${this.#address}`);
  }

  #addTeardown(conn: Connection, fn: () => void): () => void {
    const set = this.#teardowns.get(conn);
    if (!set) {
      // Connection already closed; tear down immediately.
      queueMicrotask(fn);
      return () => {};
    }
    set.add(fn);
    return () => set.delete(fn);
  }

  async #openStream(conn: Connection, signal?: AbortSignal): Promise<Stream> {
    return conn.openStream({ signal: signal ?? AbortSignal.timeout(OPEN_STREAM_TIMEOUT_MS) });
  }

  /**
   * One KPS-HTTP/1 GET exchange (PROTOCOL.md §3): write the request, FIN,
   * then read the response; the body ends at EOF.
   *
   * @param path Absolute request path (e.g. "/bootstrap.zip.zst").
   * @param opts Optional `signal` bounding the whole exchange.
   */
  async fetch(path: string, opts: { signal?: AbortSignal } = {}): Promise<GatewayResponse> {
    const { signal } = opts;
    const conn = await this.#connection(signal);
    const stream = await this.#openStream(conn, signal);
    const reader = stream.readable.getReader();
    const removeTeardown = this.#addTeardown(conn, () => {
      reader.cancel(new Error('kps connection closed')).catch(() => {});
      stream.close().catch(() => {});
    });

    try {
      const writer = stream.writable.getWriter();
      await writer.write(enc.encode(`GET ${path} HTTP/1.1\r\nHost: ${this.#certhash}\r\n\r\n`));
      await writer.close(); // FIN — delimits the (empty) request body

      // Only the head is deadlined, not the body: a bootstrap snapshot is
      // megabytes and a slow link must not be mistaken for a dead gateway.
      const { status, statusText, headers, extra } = await abortRace(
        readHead(reader), signal, `GET ${path}`,
      );
      const chunks: Uint8Array[] = [];
      let length = 0;
      if (extra.length) {
        chunks.push(extra);
        length += extra.length;
      }
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        if (value?.length) {
          chunks.push(value);
          length += value.length;
        }
      }
      return { status, statusText, headers, body: concat(chunks, length) };
    } finally {
      removeTeardown();
      stream.close().catch(() => {});
    }
  }

  /**
   * Open a TCP tunnel to a Tor relay via CONNECT (PROTOCOL.md §4). After
   * the gateway's 200 the stream is the raw byte pipe to the target.
   *
   * @param target Relay address as "ip:port" (consensus relays only).
   * @param opts Optional `signal` bounding setup (dial, stream, CONNECT reply);
   *   it does not affect the tunnel once established.
   */
  async connect(target: string, opts: { signal?: AbortSignal } = {}): Promise<ArtiSocket> {
    const { signal } = opts;
    const conn = await this.#connection(signal);
    const stream = await this.#openStream(conn, signal);
    const reader = stream.readable.getReader();
    const writer = stream.writable.getWriter();
    // No FIN here — the write half stays open for tunnel bytes.
    await writer.write(enc.encode(`CONNECT ${target} HTTP/1.1\r\nHost: ${target}\r\n\r\n`));

    let head: ResponseHead;
    try {
      head = await abortRace(readHead(reader), signal, `CONNECT ${target}`);
    } catch (e) {
      stream.close().catch(() => {});
      throw e;
    }
    if (head.status !== 200) {
      // Error responses carry a short text/plain diagnostic; read it to EOF.
      let text = dec.decode(head.extra);
      try {
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          text += dec.decode(value, { stream: true });
        }
      } catch { /* best-effort diagnostic */ }
      stream.close().catch(() => {});
      throw new Error(`CONNECT ${target}: ${head.status} ${text.trim() || head.statusText}`);
    }

    // The CONNECT exchange is done; hand the raw tunnel to the consumer as
    // WHATWG streams. Release the writer we used for the request line so
    // ArtiSocket.writable is available; keep `reader` (it holds any body
    // bytes that arrived with the head) and expose it, extra bytes first,
    // as a pull-based readable that only pulls from the network on demand.
    writer.releaseLock();

    const readable = new ReadableStream<Uint8Array>({
      start(controller) {
        if (head.extra.length) controller.enqueue(new Uint8Array(head.extra));
      },
      async pull(controller) {
        try {
          const { done, value } = await reader.read();
          if (done) controller.close(); // server FIN — target closed its write half
          else if (value?.length) controller.enqueue(new Uint8Array(value));
        } catch (e) {
          controller.error(e);
        }
      },
      cancel(reason) {
        reader.cancel(reason).catch(() => {});
      },
    });

    // stream.closed may reject (kps surfaces the close reason that way, e.g.
    // null); normalize both outcomes to a resolved ArtiSocketCloseInfo so this
    // never becomes an unhandled rejection.
    const closed: Promise<ArtiSocketCloseInfo> = stream.closed.then(
      (info) => ({ ok: info.ok, reason: info.ok ? undefined : (info.reason?.code ?? 'error') }),
      (err) => ({ ok: false, reason: err?.code ?? err?.message ?? 'closed' }),
    );

    // The JS kps client doesn't reliably settle streams when the connection
    // dies (kps ISSUES #4), which would hang a pending read forever. Cancel
    // the reader and close the stream on connection teardown.
    const removeTeardown = this.#addTeardown(conn, () => {
      reader.cancel(new Error('kps connection closed')).catch(() => {});
      stream.close().catch(() => {});
    });
    stream.closed.then(removeTeardown, removeTeardown);

    return new ArtiSocket({
      readable,
      writable: stream.writable,
      closed,
      closeWrite: () => stream.closeWrite(),
      close: () => { stream.close().catch(() => {}); },
    });
  }

  /** Close the underlying KPS connection (all streams/tunnels with it). */
  close(): void {
    this.#closed = true;
    const p = this.#connPromise;
    this.#connPromise = null;
    if (p) {
      p.then((conn) => conn.close()).catch(() => {});
    }
  }
}
